package main

import "fmt"

var relFrom12115,relTo12115,relList12115 uintptr
func showRelatoriosUI12115(){if !ensureDB(){return};currentModule="relatorios";clearContent();header("Lucro / Relatórios","");add("STATIC","De (AAAA-MM-DD)",0,250,120,140,20,0);relFrom12115=add("EDIT","",WS_BORDER|ES_AUTOHSCROLL,250,143,140,30,4901);add("STATIC","Até (AAAA-MM-DD)",0,405,120,150,20,0);relTo12115=add("EDIT","",WS_BORDER|ES_AUTOHSCROLL,405,143,140,30,4902);add("BUTTON","Resumo / Lucro",0,565,139,145,38,4903);add("BUTTON","Vendas por dia",0,720,139,135,38,4904);add("BUTTON","Mais vendidos",0,865,139,125,38,4905);add("BUTTON","Estoque baixo",0,1000,139,130,38,4906);add("BUTTON","Validade 30 dias",0,1140,139,130,38,4907);relList12115=add("LISTBOX","",WS_BORDER|WS_VSCROLL|LBS_NOINTEGRALHEIGHT,250,195,1020,490,4910);loadProfitUI12115()}
func relReset12115(title string){listReset(relList12115);listAdd(relList12115,title)}
func loadProfitUI12115(){m,e:=profitSummary12115(getText(relFrom12115),getText(relTo12115));if e!=nil{msgErr(e.Error());return};relReset12115("RESUMO FINANCEIRO");listAdd(relList12115,"Faturamento: R$ "+m["faturamento"]);listAdd(relList12115,"Custo:       R$ "+m["custo"]);listAdd(relList12115,"Lucro:       R$ "+m["lucro"]);listAdd(relList12115,"Dízimo:      R$ "+m["dizimo"])}
func loadSalesReportUI12115(){rows,e:=salesSummary12115(getText(relFrom12115),getText(relTo12115));if e!=nil{msgErr(e.Error());return};relReset12115("DATA         VENDAS    FATURAMENTO       CUSTO          LUCRO          DÍZIMO");for _,r:=range rows{listAdd(relList12115,fmt.Sprintf("%-12s %6s   R$ %11s   R$ %11s   R$ %11s   R$ %11s",r[0],r[1],r[2],r[3],r[4],r[5]))}}
func loadTopProductsUI12115(){rows,e:=topProducts12115("");if e!=nil{msgErr(e.Error());return};relReset12115("PRODUTO                                                QUANTIDADE       FATURAMENTO");for _,r:=range rows{listAdd(relList12115,fmt.Sprintf("%-54s %10s       R$ %11s",clip(r[0],54),r[1],r[2]))}}
func loadLowStockUI12115(){rows,e:=lowStockReport12115();if e!=nil{msgErr(e.Error());return};relReset12115("CÓDIGO           PRODUTO                                      ESTOQUE      MÍNIMO       VALIDADE");for _,r:=range rows{listAdd(relList12115,fmt.Sprintf("%-16s %-44s %10s  %10s   %s",r[1],clip(r[2],44),r[3],r[4],r[5]))}}
func loadValidityReportUI12115(){rows,e:=validityReport12115(30);if e!=nil{msgErr(e.Error());return};relReset12115("CÓDIGO           PRODUTO                                      VALIDADE       ESTOQUE");for _,r:=range rows{listAdd(relList12115,fmt.Sprintf("%-16s %-44s %-12s   %s",r[1],clip(r[2],44),r[3],r[4]))}}
func handleRelatoriosUI12115(id int)bool{switch id{case 4903:loadProfitUI12115();case 4904:loadSalesReportUI12115();case 4905:loadTopProductsUI12115();case 4906:loadLowStockUI12115();case 4907:loadValidityReportUI12115();default:return false};return true}
